add_action('wp_ajax_pa_pdf_visual_fixture',function(){
 if(!current_user_can('manage_options'))wp_die('Forbidden');
 $ids=get_posts(['post_type'=>'pelham_application','post_status'=>'private','fields'=>'ids','numberposts'=>100]);$source=0;foreach($ids as $id){$p=pa_get($id);if($p['kind']==='claim'&&(int)get_post_meta($id,'_pa_revision',true)>0){$source=$id;break;}}if(!$source)wp_die('No claim fixture');
 $p=pa_get($source,'_pa_revision_1');$p['test']=true;
 $p['data']=array_merge($p['data'],['bol'=>'4322334','shipment_date'=>'2026-10-01','payment_method'=>'Prepaid','shipper_name'=>'Harbor Distribution LLC','shipper_address'=>'1250 Harbor Boulevard','consignee_name'=>'Atlantic Supply Company','consignee_address'=>'8400 NW 25th Street','shipper_contact'=>'Maria Garcia','consignee_contact'=>'James Wilson','shipper_phone'=>'(323) 201-4995','consignee_phone'=>'(305) 555-0187','shipper_fax'=>'','consignee_fax'=>'','shipper_email'=>'shipping@harbor.example','consignee_email'=>'receiving@atlantic.example','commodity'=>'Packaged household goods','quantity'=>'432','weight'=>'4,320 lb','lost_pieces'=>'432 cartons missing from the shipment. Delivery receipt lists the shortage.','damage'=>'Outer cartons crushed on arrival. Several units show impact damage on their corners. Photos and invoice supplied.','claim_amount'=>'432324.00','claim_signer'=>'Maria Garcia']);
 $im=imagecreatetruecolor(1000,280);imagefill($im,0,0,imagecolorallocate($im,255,255,255));$ink=imagecolorallocate($im,15,35,25);imagesetthickness($im,2);imageline($im,480,150,486,124,$ink);imageline($im,486,124,492,149,$ink);imageline($im,492,149,503,125,$ink);imageline($im,503,125,510,148,$ink);imagearc($im,516,143,18,17,0,300,$ink);ob_start();imagejpeg($im,null,95);$bytes=ob_get_clean();imagedestroy($im);
 $image=pa_image('data:image/jpeg;base64,'.base64_encode($bytes));$p['signatures']['claim']['image']=$image;$p['signatures']['claim']['name']='Maria Garcia';$p['signatures']['claim']['data_hash']=pa_fingerprint($p);
 $id=wp_insert_post(['post_type'=>'pelham_application','post_status'=>'private','post_title'=>'TEST — PDF alignment']);update_post_meta($id,'_pa_test',1);update_post_meta($id,'_pa_kind','claim');update_post_meta($id,'_pa_status','received');update_post_meta($id,'_pa_revision',1);pa_put($id,$p);pa_put($id,$p,'_pa_revision_1');
 $temp=[];$before=hash('sha256',base64_decode($image['base64']));$crop=pa_pdf_signature_file($image,$temp);$dimensions=[$crop[1],$crop[2]];foreach($temp as $file)unlink($file);$pdf=pa_original_pdf($id,1,'claim');$after=pa_get($id,'_pa_revision_1');
 $long=$p;$long['data']['damage']=str_repeat('LONG_DESCRIPTION_PRESERVED ',50);$long['data']['shipper_name']=str_repeat('LONG_COMPANY_NAME ',12);pa_put($id,$long,'_pa_revision_2');
 wp_send_json(['id'=>$id,'crop'=>$dimensions,'unchanged'=>$before===hash('sha256',base64_decode($after['signatures']['claim']['image']['base64'])),'pdf'=>base64_encode($pdf),'long_pdf'=>base64_encode(pa_original_pdf($id,2,'claim'))]);
});
